private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int length = bb.remaining();
    while (i < length) {
        byte octet = bb.get(i);
        if ((octet & 0xFF) < 0x80) { // ASCII character
            sb.append((char) octet);
            i++;
        } else if (((octet & 0xE0) == 0xC0) && ((octet & 0x1F) >= 0x02)) { // 2-octet sequence
            byte octet2 = bb.get(i + 1);
            if ((octet2 & 0xC0) == 0x80) {
                sb.append((char) (((octet & 0x1F) << 6) | (octet2 & 0x3F)));
                i += 2;
            } else {
                throw new UTFDataFormatException("MalformedInput at index " + i);
            }
        } else if (((octet & 0xF0) == 0xE0) && ((octet & 0x0F) >= 0x03)) { // 3-octet sequence
            byte octet2 = bb.get(i + 1);
            byte octet3 = bb.get(i + 2);
            if (((octet2 & 0xC0) == 0x80) && ((octet3 & 0xC0) == 0x80)) {
                sb.append((char) (((octet & 0x0F) << 12) | ((octet2 & 0x3F) << 6) | (octet3 & 0x3F)));
                i += 3;
            } else {
                throw new UTFDataFormatException("MalformedInput at index " + i);
            }
        } else if (((octet & 0xF8) == 0xF0) && ((octet & 0x07) >= 0x04)) { // 4-octet sequence
            byte octet2 = bb.get(i + 1);
            byte octet3 = bb.get(i + 2);
            byte octet4 = bb.get(i + 3);
            if (((octet2 & 0xC0) == 0x80) && ((octet3 & 0xC0) == 0x80) && ((octet4 & 0xC0) == 0x80)) {
                sb.append((char) (((octet & 0x07) << 18) | ((octet2 & 0x3F) << 12) | ((octet3 & 0x3F) << 6) | (octet4 & 0x3F)));
                i += 4;
            } else {
                throw new UTFDataFormatException("MalformedInput at index " + i);
            }
        } else {
            throw new UTFDataFormatException("MalformedInput at index " + i);
        }
    }
    return i;
}

