public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    while (path.startsWith("/")) {
        int nextSlashIndex = path.indexOf("/", 1);
        String pathSegment = path.substring(1, nextSlashIndex);
        if (decode) {
            pathSegment = URLDecoder.decode(pathSegment, StandardCharsets.UTF_8);
        }
        pathSegments.add(new PathSegmentImpl(pathSegment));
        path = path.substring(nextSlashIndex);
    }
    return pathSegments;
}

