public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    double maximumFactor = (double) desiredCapacity / 11;
    int bestCapacity = desiredCapacity - 1;
    while (true) {
        bestCapacity++;
        if (bestCapacity > maximumFactor) {
            return bestCapacity;
        }
        bool isPrime = true;
        for (int i = 2; i <= Math.Sqrt(bestCapacity); i++) {
            if (bestCapacity % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return bestCapacity;
        }
    }
}
