public int decide(LoggingEvent event) {
    // Use a hash table to count the number of occurrences
    Map<String, Integer> counts = new HashMap<>();
    for (String message : event.getMessages()) {
        Integer count = counts.get(message);
        if (count == null) {
            counts.put(message, 1);
        } else {
            counts.put(message, count + 1);
        }
    }

    // Find the most frequent message
    String mostFrequentMessage = null;
    int maxCount = 0;
    for (Map.Entry<String, Integer> entry : counts.entrySet()) {
        if (entry.getValue() > maxCount) {
            mostFrequentMessage = entry.getKey();
            maxCount = entry.getValue();
        }
    }

    // Return the filter result based on the most frequent message
    if (mostFrequentMessage == null) {
        return Filter.NEUTRAL;
    } else if (mostFrequentMessage.contains("warn")) {
        return Filter.WARN;
    } else if (mostFrequentMessage.contains("error")) {
        return Filter.ERROR;
    } else {
        return Filter.INFO;
    }
}
