public int readRawVarint32() throws IOException {
    int temp = 0;
    for (int i = 0; i < 32; i += 7) {
        if (input.available() == 0 || (temp = input.read()) == -1) {
            throw new IOException("Unable to read raw Varint32 value.");
        }
        temp &= ~0x80;
        if ((temp & 0x80) == 0) {
            break;
        }
        temp = (temp << 7) + (input.read() & 0x7f);
    }
    return temp;
}

